const item = $('Webhook WAHA').first().json;
const lookup = $input.first().json || {};
const body = item.body || {};
const payload = body.payload || {};

const event = body.event || null;
const rawFrom = String(payload.from || '');
const digits = (value) => String(value || '').replace(/[^0-9]/g, '');

// A chat WhatsApp addresses by LID shows up as <lid>@lid, and a reply sent to
// <lid>@c.us is rejected by WhatsApp Web. The lids lookup turns it into the
// real <phone>@c.us, which is also the key the outbound flow stores in
// anteraja_chat_state.
const pn = typeof lookup.pn === 'string' && lookup.pn !== '' ? lookup.pn : '';
const chatId = pn !== '' ? pn : rawFrom;

const text = String(payload.body || '').trim();

// Id pesan WhatsApp: satu balasan dobel tidak boleh dijalankan dua kali.
const rawMessageId = payload.id;
const messageId = typeof rawMessageId === 'string' ? rawMessageId : ((rawMessageId && (rawMessageId._serialized || rawMessageId.id)) || null);
const phone = digits(pn !== '' ? pn : rawFrom);
const isGroup = rawFrom.endsWith('@g.us');
const isStatus = rawFrom === 'status@broadcast';
const shouldProcess = event === 'message'
  && payload.fromMe !== true
  && !isGroup
  && !isStatus
  && text.length > 0
  && phone.length >= 8;

return [{ json: {
  should_process: shouldProcess,
  phone: phone,
  chat_id: chatId,
  text: text,
  push_name: payload.notifyName || null,
  message_id: messageId
} }];

const msg = $('Normalisasi').first().json;
const match = String(msg.text || '').toUpperCase().match(/AJ-FRZ-\d{4,}/);

return [{ json: { resi: match ? match[0] : null } }];

const msg = $('Normalisasi').first().json;
const state = $('Ambil State').first().json || {};
const lookup = $input.first().json || {};
const detected = $('Deteksi Resi').first().json || {};

const slots = ['09:00-11:00', '11:00-13:00', '13:00-15:00', '15:00-17:00', '17:00-19:00'];
const today = $now.setZone('Asia/Jakarta').toFormat('yyyy-LL-dd');
const tomorrow = $now.setZone('Asia/Jakarta').plus({ days: 1 }).toFormat('yyyy-LL-dd');
const dayAfter = $now.setZone('Asia/Jakarta').plus({ days: 2 }).toFormat('yyyy-LL-dd');

const stateContext = state.context && typeof state.context === 'object' ? state.context : {};
const storedWindow = typeof stateContext.window === 'string' && stateContext.window !== '' ? stateContext.window : null;

const stateDecision = typeof stateContext.decision === 'string' && stateContext.decision !== '' ? stateContext.decision : null;

// When the app recognises the parcel its answer is the fresher truth: the
// stored row only reflects the last notification, so it lags behind an admin
// reschedule or a recheck decision.
const found = lookup.found === true;
const lookupWindow = found ? (lookup.window || null) : null;
const tracking = found ? (lookup.tracking_number || state.tracking_number || null) : (state.tracking_number || null);
const pendingWindow = lookupWindow || storedWindow;
const token = found ? (lookup.client_token || state.client_token || null) : (state.client_token || null);
const template = found ? (lookup.template || 'none') : (state.last_template || 'none');
const statusLabel = found ? (lookup.status_label || null) : null;

const system = [
  'Anda asisten operasional Anteraja Frozen yang membaca balasan pembeli di WhatsApp.',
  'Balas HANYA dengan JSON valid tanpa penjelasan tambahan.',
  'Skema: {"intent":"confirm_schedule|request_reschedule|other","option":null,"proposed_date":null,"proposed_slot":null,"confidence":0.0}',
  'Aturan:',
  '- confirm_schedule: pembeli menyetujui jadwal penerimaan paket.',
  '- request_reschedule: pembeli meminta jadwal lain; isi proposed_slot dari daftar: ' + slots.join(', ') + ', dan isi proposed_date (YYYY-MM-DD) HANYA kalau pembeli menyebut tanggal; kalau hanya jam, biarkan proposed_date null.',
  '- other: maksud tidak jelas.',
  'Tanggal hari ini (Asia/Jakarta) adalah ' + today + '; besok ' + tomorrow + '; lusa ' + dayAfter + '.',
  'Bila pembeli menyebut nomor tanggal tanpa bulan (contoh: "tanggal 23", "tgl 22"), pakai bulan dan tahun dari hari ini; bila tanggal itu sudah lewat dari hari ini, pakai bulan berikutnya. Isi proposed_date dengan format YYYY-MM-DD.',
  'Bila pembeli menyebut jam (contoh: "jam 13.00", "pukul 13", "13:00"), pilih proposed_slot dari daftar di atas yang memuat jam itu; jangan mengarang slot di luar daftar.',
  'Konteks: pesan terakhir dari sistem = ' + template + '; resi = ' + (tracking || 'tidak diketahui') + '.'
].join('\n');

return [{ json: {
  phone: msg.phone,
  chat_id: msg.chat_id,
  text: msg.text,
  push_name: msg.push_name,
  tracking_number: tracking,
  client_token: token,
  last_template: template,
  status_label: statusLabel,
  pending_window: pendingWindow,
  decision: stateDecision,
  resi_attempt: detected.resi || null,
  role: found ? (lookup.role || null) : null,
  recipient_type: (typeof stateContext.recipient_type === 'string' ? stateContext.recipient_type : null),
  message_id: msg.message_id || null,
  lookup_found: found,
  today: today,
  slots: slots,
  llm_body: {
    model: 'deepseek-v4-flash',
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: msg.text }
    ]
  }
} }];

const ctx = $('Siapkan Konteks').first().json;
const llm = $input.first().json || {};

let llmIntent = null;
let llmOption = null;
let llmDate = null;
let llmSlot = null;
let confidence = 0;

try {
  const content = llm.choices && llm.choices[0] && llm.choices[0].message ? llm.choices[0].message.content : null;
  if (typeof content === 'string') {
    const parsed = JSON.parse(content);
    llmIntent = parsed.intent || null;
    llmOption = parsed.option === undefined || parsed.option === null ? null : parseInt(parsed.option, 10);
    confidence = parsed.confidence || 0;
    llmDate = parsed.proposed_date || null;
    llmSlot = parsed.proposed_slot || null;
  }
} catch (error) {
  llmIntent = null;
}

const text = String(ctx.text || '').toLowerCase().trim();
const template = ctx.last_template || 'none';
// Both notices ask the buyer the same question: the first schedule and the one
// the admin proposed afterwards.
const confirming = template === 'schedule_request' || template === 'schedule_rescheduled';
const slots = ctx.slots || [];
const resi = ctx.tracking_number || '-';
const base = ctx.client_token ? 'http://anteraja-hackathon-service/api/guest/' + ctx.client_token : null;
const has = (pattern) => pattern.test(text);

const nowJakarta = $now.setZone('Asia/Jakarta');
const todayJakarta = nowJakarta.toFormat('yyyy-LL-dd');
const tomorrowJakarta = nowJakarta.plus({ days: 1 }).toFormat('yyyy-LL-dd');

// The API rejects a pickup window less than two hours away, so a customer who
// names only a time (or one that has already passed) is asked for a date
// instead of being sent into a guaranteed rejection.
const earliestStamp = nowJakarta.plus({ hours: 2 }).toFormat('yyyyLLddHHmm');
const isFarEnough = (date, slot) => {
  if (!date || !slot) return false;
  const stamp = String(date).replace(/-/g, '') + String(slot).split('-')[0].replace(':', '');
  return /^\d{12}$/.test(stamp) && stamp >= earliestStamp;
};

// Reading the date and the window from what the customer typed. This is the
// authority for the two-hour rule: a dated request is judged against the date
// the customer wrote, never against today's clock, and a text that names only
// a time means tomorrow.
const MONTHS = { januari: 1, februari: 2, maret: 3, april: 4, mei: 5, juni: 6, juli: 7, agustus: 8, september: 9, oktober: 10, november: 11, desember: 12, jan: 1, feb: 2, mar: 3, apr: 4, jun: 6, jul: 7, agu: 8, agt: 8, ags: 8, sep: 9, sept: 9, okt: 10, nov: 11, des: 12 };
const WEEKDAYS = { minggu: 0, ahad: 0, senin: 1, selasa: 2, rabu: 3, kamis: 4, jumat: 5, jum: 5, sabtu: 6 };

function pad2(value) {
  return String(value).padStart(2, '0');
}
function isoOf(year, month, day) {
  const dt = new Date(Date.UTC(year, month - 1, day));
  return dt.getUTCFullYear() + '-' + pad2(dt.getUTCMonth() + 1) + '-' + pad2(dt.getUTCDate());
}
function shiftIso(iso, days) {
  const parts = iso.split('-').map(Number);
  const dt = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2] + days));
  return dt.getUTCFullYear() + '-' + pad2(dt.getUTCMonth() + 1) + '-' + pad2(dt.getUTCDate());
}
function daysBetween(from, to) {
  const a = from.split('-').map(Number);
  const b = to.split('-').map(Number);
  return Math.round((Date.UTC(b[0], b[1] - 1, b[2]) - Date.UTC(a[0], a[1] - 1, a[2])) / 86400000);
}
function parseDate(input, today) {
  const say = String(input || '').toLowerCase();
  if (/\b(hari ini|today)\b/.test(say)) return today;
  if (/\b(besok|esok)\b/.test(say)) return shiftIso(today, 1);
  if (/\blusa\b/.test(say)) return shiftIso(today, 2);
  if (/\b(minggu|pekan)\s*depan\b/.test(say)) return shiftIso(today, 7);
  const inDays = say.match(/\b(\d{1,2})\s*hari\s*(?:lagi|kemudian|ke depan)\b/);
  if (inDays) return shiftIso(today, parseInt(inDays[1], 10));
  const weekday = say.match(/\b(minggu|ahad|senin|selasa|rabu|kamis|jumat|jum|sabtu)\b/);
  if (weekday) {
    const parts = today.split('-').map(Number);
    const current = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2])).getUTCDay();
    const delta = (WEEKDAYS[weekday[1]] - current + 7) % 7;
    return shiftIso(today, delta === 0 ? 7 : delta);
  }
  const dayMonth = say.match(/\b(\d{1,2})\s*(januari|februari|maret|april|mei|juni|juli|agustus|september|oktober|november|desember|jan|feb|mar|apr|jun|jul|agu|agt|ags|sep|sept|okt|nov|des)\b(?:\s*(\d{4}))?/);
  if (dayMonth) {
    const year = dayMonth[3] ? parseInt(dayMonth[3], 10) : parseInt(today.slice(0, 4), 10);
    return isoOf(year, MONTHS[dayMonth[2]], parseInt(dayMonth[1], 10));
  }
  const slash = say.match(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/);
  if (slash) {
    let year = slash[3] ? parseInt(slash[3], 10) : parseInt(today.slice(0, 4), 10);
    if (year < 100) year += 2000;
    return isoOf(year, parseInt(slash[2], 10), parseInt(slash[1], 10));
  }
  const dayOnly = say.match(/\b(?:tanggal|tgl)\s*(\d{1,2})\b/);
  if (dayOnly) {
    const parts = today.split('-').map(Number);
    const day = parseInt(dayOnly[1], 10);
    let candidate = isoOf(parts[0], parts[1], day);
    if (daysBetween(today, candidate) < 0) candidate = isoOf(parts[0], parts[1] + 1, day);
    return candidate;
  }
  return null;
}
function parseSlot(input, choices) {
  const say = String(input || '');
  for (const choice of choices) { if (say.indexOf(choice) !== -1) return choice; }
  let match = say.match(/\b(\d{1,2})[:.](\d{2})\b/);
  let hour = match ? parseInt(match[1], 10) : null;
  if (hour === null) {
    match = say.match(/\b(?:jam|pukul)\s*(\d{1,2})\b/);
    if (match) hour = parseInt(match[1], 10);
  }
  if (hour === null) return null;
  for (const choice of choices) { if (parseInt(choice.split('-')[0].split(':')[0], 10) === hour) return choice; }
  return null;
}

// Hanya admin yang bertindak lewat balasan WhatsApp; kurir memakai aplikasi.
// jawaban aplikasi (nomor ini milik siapa) atau dari baris state yang mencatat
// siapa penerima notifikasi terakhir — bukan dari tebakan isi pesan.
const staffRole = ctx.role === 'ADMIN' || ctx.recipient_type === 'ADMIN' ? 'ADMIN' : null;
const isCourierNumber = ctx.role === 'COURIER' || ctx.recipient_type === 'COURIER';

function classifyAdminAction(body) {
  const say = String(body || '').toLowerCase();
  const has = (pattern) => pattern.test(say);

  if (has(/(kembalikan|kembali|retur|batalkan|tarik)/)) {
    return { action: 'return', category: null };
  }
  if (has(/(kirim ulang|resend|ganti barang|pengiriman ulang)/)) {
    return { action: 'resend', category: null };
  }
  if (has(/(periksa ulang|cek ulang|recheck|inspeksi)/)) {
    return { action: 'recheck', category: null };
  }
  if (has(/(jadwal ulang|jadwalkan ulang|tunda|reschedule)/)) {
    return { action: 'reschedule', category: null };
  }
  if (has(/(lanjut|lanjutkan|kompensasi|teruskan)/)) {
    return { action: 'proceed', category: null };
  }

  return { action: null, category: null };
}

const STAFF_HELP = {
  ADMIN: 'Halo! Balas keputusan kendala beserta nomor resinya: *KEMBALIKAN*, *KIRIM ULANG*, *LANJUT*, *PERIKSA ULANG*, atau *JADWALKAN ULANG*. Anteraja Frozen \u2744\ufe0f'
};

if (isCourierNumber) {
  return [{ json: {
    intent: 'info:courier',
    option: null,
    confidence: 1,
    app_url: null,
    app_body: {},
    reply_text: 'Kurir tidak bertindak lewat WhatsApp. Gunakan aplikasi Anteraja Kurir untuk menerima tugas dan memperbarui pengiriman. Anteraja Frozen \u2744\ufe0f',
    next_template: null,
    phone: ctx.phone,
    tracking_number: ctx.tracking_number,
    client_token: ctx.client_token
  } }];
}

if (staffRole === 'ADMIN') {
  const staff = classifyAdminAction(ctx.text);
  const staffResi = ctx.resi_attempt || ctx.tracking_number || null;

  return [{ json: {
    intent: staff.action ? ('staff:' + staff.action) : 'staff:unknown',
    option: null,
    confidence: 1,
    app_url: staff.action ? 'http://anteraja-hackathon-service/api/internal/whatsapp/action' : null,
    app_body: staff.action ? {
      phone: ctx.phone,
      action: staff.action,
      resi: staffResi,
      note: ctx.text,
      category: staff.category,
      text: ctx.text,
      message_id: ctx.message_id || null
    } : {},
    reply_text: staff.action
      ? 'Baik, permintaan Anda sedang kami proses. Anteraja Frozen \u2744\ufe0f'
      : STAFF_HELP.ADMIN,
    next_template: staff.action
      ? ('admin_decision:' + staff.action.toUpperCase())
      : null,
    phone: ctx.phone,
    tracking_number: ctx.tracking_number,
    client_token: ctx.client_token
  } }];
}

// What was this conversation waiting for? Only that step can be acted on.
let action = null;
let option = null;
let proposedDate = null;
let proposedSlot = null;

if (confirming) {
  // A message that names a day or a window is a request, whatever else it says:
  // "tanggal 16 jam 09:00-11:00 bisa?" asks for that window, it does not accept
  // the standing one. Only an acknowledgement that names nothing confirms it,
  // so a polite "bisa"/"oke" never overrides a date or a time.
  const namesWindow = parseDate(text, todayJakarta) !== null || parseSlot(text, slots) !== null;
  const saysReschedule = has(/\b(jadwal lain|minta jadwal|ubah|ganti|tunda|reschedule|besok|tanggal|jam|pukul)\b/);
  const saysConfirm = has(/\b(siap|ya|iya|oke|ok|setuju|terima|konfirmasi|hadir)\b/);

  if (namesWindow || saysReschedule || llmIntent === 'request_reschedule') {
    action = 'reschedule';
  } else if (saysConfirm || llmIntent === 'confirm_schedule') {
    action = 'confirm';
  }

  if (action === 'reschedule') {
    proposedDate = llmDate;
    proposedSlot = llmSlot;
  }
}

if (action && !base) {
  // The app never told us which package this is, so nothing can be applied.
  action = null;
}

// The text decides the date; the model only fills gaps. A request that names a
// day is dated to that day, and a text that names only a time means tomorrow.
if (action === 'reschedule') {
  const textDate = parseDate(text, todayJakarta);
  const textSlot = parseSlot(text, slots);
  if (textSlot) proposedSlot = textSlot;
  if (textDate) {
    proposedDate = textDate;
  } else if (textSlot) {
    proposedDate = tomorrowJakarta;
  } else if (!proposedDate || !/^\d{4}-\d{2}-\d{2}$/.test(String(proposedDate))) {
    proposedDate = null;
  }
}

// Why the window the customer named cannot be applied yet, so the reply names
// the real cause instead of always blaming the two-hour lead. A future day is
// always far enough; only a same-day window inside the lead is too soon.
let rescheduleReason = null;
if (action === 'reschedule' && proposedSlot && slots.indexOf(proposedSlot) !== -1) {
  if (!proposedDate || !/^\d{4}-\d{2}-\d{2}$/.test(String(proposedDate))) {
    rescheduleReason = 'no_date';
  } else if (String(proposedDate) < todayJakarta) {
    rescheduleReason = 'past';
  } else if (!isFarEnough(proposedDate, proposedSlot)) {
    rescheduleReason = 'too_soon';
  }
}

let appUrl = null;
let appBody = {};
let reply = null;
let nextTemplate = null;

if (action === 'confirm') {
  appUrl = base + '/schedule/confirm';
  reply = 'Terima kasih, Kak! Jadwal penerimaan paket ' + resi + ' sudah dikonfirmasi dan paket akan kami antar sesuai jadwal. Anteraja Frozen \u2744\ufe0f';
  nextTemplate = 'confirmed';
} else if (action === 'reschedule' && rescheduleReason === null && proposedDate && proposedSlot && slots.indexOf(proposedSlot) !== -1 && isFarEnough(proposedDate, proposedSlot)) {
  appUrl = base + '/schedule/reschedule';
  appBody = { date: proposedDate, slot: proposedSlot };
  reply = 'Terima kasih, Kak! Jadwal pengantaran resi ' + resi + ' sudah kami ubah ke ' + proposedDate + ' (' + proposedSlot + '). Anteraja Frozen \u2744\ufe0f';
  nextTemplate = 'confirmed';
} else if (action === 'reschedule' && rescheduleReason === 'too_soon') {
  reply = 'Mohon maaf Kak, jadwal itu kurang dari 2 jam dari sekarang. Kirim jam saja untuk jadwal besok (contoh: 11:00-13:00), atau tuliskan tanggal dan jam lain. Anteraja Frozen \u2744\ufe0f';
} else if (action === 'reschedule' && rescheduleReason === 'past') {
  reply = 'Mohon maaf Kak, tanggal itu sudah lewat. Kirim tanggal pengantaran berikutnya beserta jam: ' + slots.join(', ') + '. Anteraja Frozen \u2744\ufe0f';
} else if (action === 'reschedule' && proposedSlot && slots.indexOf(proposedSlot) !== -1) {
  reply = 'Baik Kak, mohon tuliskan tanggal penerimaan untuk jam ' + proposedSlot + '. Pilihan jam: ' + slots.join(', ') + '. Anteraja Frozen \u2744\ufe0f';
} else if (action === 'reschedule') {
  reply = 'Baik Kak, mohon tuliskan tanggal dan pilihan jam penerimaan: ' + slots.join(', ') + '. Anteraja Frozen \u2744\ufe0f';
} else if (confirming) {
  reply = 'Paket ' + resi + ' masih menunggu konfirmasi jadwal' + (ctx.pending_window ? ' untuk ' + ctx.pending_window : '') + '. Balas *SIAP* untuk konfirmasi, atau *JADWAL LAIN* untuk meminta jadwal pengganti. Anteraja Frozen \u2744\ufe0f';
} else if (template === 'delivered') {
  reply = 'Paket ' + resi + ' sudah diterima. Terima kasih telah menggunakan Anteraja Frozen! \u2744\ufe0f';
} else if (template === 'courier_arrived') {
  reply = 'Kurir kami sudah tiba di lokasi untuk paket ' + resi + '. Mohon siapkan penerimaan paket beku ya, Kak. \u2744\ufe0f';
} else if (template === 'on_the_way' || template === 'in_delivery') {
  reply = 'Paket ' + resi + ' sedang dalam pengiriman' + (ctx.pending_window ? '. Estimasi penerimaan: ' + ctx.pending_window : '') + '. Anteraja Frozen \u2744\ufe0f';
} else if (template === 'issue_decision' || template.indexOf('issue_decision_update') === 0) {
  const perDecision = {
    RETURN: 'Paket ' + resi + ' sudah diputuskan untuk dikembalikan ke pengirim.',
    RESEND: 'Pengiriman ulang paket ' + resi + ' sedang disiapkan tim kami.',
    RECHECK: 'Paket ' + resi + ' sedang diperiksa ulang oleh tim operasional kami.',
    PROCEED: 'Pengiriman paket ' + resi + ' dilanjutkan sesuai keputusan tim kami.'
  };
  reply = (perDecision[ctx.decision] || ('Paket ' + resi + ' sedang ditangani tim operasional kami.')) + ' Anteraja Frozen \u2744\ufe0f';
} else if (ctx.resi_attempt && !ctx.lookup_found) {
  reply = 'Nomor resi ' + ctx.resi_attempt + ' tidak terdaftar untuk nomor WhatsApp ini. Pastikan resinya benar dan nomor ini adalah nomor pembeli yang terdaftar pada pengiriman tersebut, atau hubungi layanan pelanggan Anteraja Frozen. \u2744\ufe0f';
} else if (ctx.status_label) {
  // Nothing is pending, so answer with what the parcel is actually doing.
  reply = 'Paket ' + resi + ' statusnya: ' + ctx.status_label + (ctx.pending_window ? '. Jadwal pengantaran: ' + ctx.pending_window : '') + '. Terima kasih telah menghubungi Anteraja Frozen \u2744\ufe0f';
} else {
  reply = 'Halo! \ud83d\udc4b Kirimkan nomor resi (contoh: AJ-FRZ-0012345) agar kami bisa membantu, atau hubungi layanan pelanggan Anteraja Frozen. \u2744\ufe0f';
}

return [{ json: {
  intent: action || 'info:' + template,
  option: option,
  confidence: confidence,
  app_url: appUrl,
  app_body: appBody,
  reply_text: reply,
  next_template: nextTemplate,
  phone: ctx.phone,
  tracking_number: ctx.tracking_number,
  client_token: ctx.client_token
} }];

const decision = $('Putuskan Aksi').first().json;
const msg = $('Normalisasi').first().json;

// A failed call is wrapped differently depending on how it failed, and the
// HTTP node does not promise where the body ends up. Walk the whole error and
// use the API's own message wherever it is, instead of guessing one shape.
function appMessage(error) {
  if (!error) return null;

  const strings = [];
  const collect = (value) => {
    if (value === null || value === undefined) return;
    if (typeof value === 'string') {
      strings.push(value);
      return;
    }
    if (typeof value === 'number' || typeof value === 'boolean') {
      strings.push(String(value));
      return;
    }
    if (typeof value === 'object') {
      Object.keys(value).forEach((key) => collect(value[key]));
    }
  };
  collect(error);

  for (const raw of strings) {
    const brace = raw.indexOf('{');
    if (brace < 0) continue;
    try {
      const parsed = JSON.parse(raw.slice(brace));
      if (parsed && typeof parsed.message === 'string' && parsed.message !== '') return parsed.message;
      if (parsed && parsed.errors) {
        const first = Object.keys(parsed.errors).map((key) => parsed.errors[key])[0];
        if (Array.isArray(first) && first.length > 0) return String(first[0]);
      }
    } catch (ignored) {
      // Not a JSON body after all; keep looking.
    }
  }

  // A nested-but-plain string, e.g. { message: { message: 'Status paket ...' } }.
  const noise = /^(error|failed|bad request|unprocessable|internal server error|axioserror|nodeapierror|\d{3})$/i;
  for (const raw of strings) {
    const candidate = raw.trim();
    if (candidate.length < 12 || !/\s/.test(candidate) || !/[A-Za-z]/.test(candidate)) continue;
    if (noise.test(candidate) || /status code/i.test(candidate)) continue;
    return candidate;
  }

  // Still nothing readable: n8n's own wording beats a bare apology.
  for (const raw of strings) {
    if (/status code/i.test(raw) || /^\d{3}\b/.test(raw)) return raw.trim();
  }

  return null;
}

let text = decision.reply_text;
let ok = true;
let appResponse = null;

try {
  const app = $('Panggil App').first().json;
  appResponse = app;
  if (app && app.error) {
    ok = false;
    text = appMessage(app.error) || 'Mohon maaf, permintaan ini belum dapat kami proses. Silakan hubungi layanan pelanggan Anteraja Frozen.';
  } else if (app && app.success === false) {
    ok = false;
    text = app.message || 'Mohon maaf, permintaan ini belum dapat kami proses. Silakan hubungi layanan pelanggan Anteraja Frozen.';
  }
} catch (ignored) {
  // No app call on this path: the decided reply stands.
}

// The state row keeps what it already knew, and a failed action must not
// advance last_template so the pending step can still be answered.
const sqlLit = (value) => (value === null || value === undefined || value === '')
  ? 'null'
  : "'" + String(value).replace(/'/g, "''") + "'";

return [{ json: {
  text: text,
  chat_id: msg.chat_id,
  phone: msg.phone,
  values: [
    msg.phone,
    decision.tracking_number || null,
    decision.client_token || null,
    ok ? (decision.next_template || null) : null,
    JSON.stringify({
      last_inbound_text: msg.text,
      last_intent: decision.intent,
      last_inbound_at: new Date().toISOString()
    })
  ]
} }];
